UPDATE site_settings SET value=JSON_SET(value,'$.theme.preset','default','$.branding.theme_color','hsl(256 67% 49%)','$.branding.meta.description','İlan, iletişim satışı, hak ve site yönetimi.','$.branding.meta.og_url','https://panel.paketjet.com','$.branding.meta.og_description','PaketJet yönetim paneli') WHERE `key` IN ('ui_admin_config','paketjet__ui_admin_config') AND JSON_VALID(value);
UPDATE site_settings SET value=JSON_SET(value,'$.nav.labels.general','Genel','$.nav.labels.finance','Finans','$.nav.items.dashboard','Genel bakış','$.nav.items.wallets','Eski TL arşivi','$.nav.items.ilan_purchases','İletişim satışları','$.nav.items.payments','Ödeme incelemeleri','$.nav.items.credits','İlan alma hakları','$.nav.items.support_tickets','Destek talepleri','$.nav.items.faqs','Sık sorulan sorular','$.nav.items.pages','Sayfalar ve yasal içerik') WHERE `key` IN ('ui_admin','paketjet__ui_admin') AND JSON_VALID(value);
